SELECT ap.subject_id, ap.hadm_id, ap.admittime, ap.dischtime, ap.deathtime, ap.admission_type, ap.admit_provider_id, ap.admission_location, ap.discharge_location, ap.insurance, ap.language, ap.marital_status, ap.race, ap.edregtime, ap.edouttime, ap.hospital_expire_flag, fp.gender, fp.anchor_age, fp.anchor_year, fp.anchor_year_group, ish.instability_score, lag(ish.instability_score) OVER (PARTITION BY ish.subject_id ORDER BY ish.charttime) AS previous_instability_score, lead(ish.instability_score) OVER (PARTITION BY ish.subject_id ORDER BY ish.charttime) AS next_instability_score, (ish.instability_score - coalesce(ish.previous_instability_score, 0)) / NULLIF(coalesce(ish.next_instability_score, 1), 0) AS instability_change_rate, (ap.dischtime - ap.admittime) AS length_of_stay FROM acute_pancreatitis ap JOIN first_48_hours fh ON ap.hadm_id = fh.hadm_id JOIN instability_scores ish ON fh.subject_id = ish.subject_id JOIN female_patients fp ON fp.anchor_age BETWEEN 65 AND 75;